"""Shared feature metadata helpers for converter-written ``meta/info.json`` files."""

from __future__ import annotations

import json
import os
from copy import deepcopy
from pathlib import Path
from typing import Any, Callable, Mapping


OriginResolver = Mapping[str, str] | Callable[[str], str]

LEROBOT_GENERATED_ORIGINS = {
    "timestamp": "generated by LeRobot from frame_index and dataset fps",
    "frame_index": "generated by LeRobot from frame order within each episode",
    "episode_index": "generated by LeRobot from converted episode order",
    "index": "generated by LeRobot from global converted frame order",
    "task_index": "generated by LeRobot from the converted frame task string",
}


def source_metadata_suffix(embodiment: str, origin_data: str) -> str:
    embodiment = embodiment.strip()
    origin_data = origin_data.strip()
    if not embodiment:
        raise ValueError("embodiment must not be empty")
    if not origin_data:
        raise ValueError("OriginData must not be empty")
    return f"Embodiment: {embodiment}. OriginData: {origin_data}."


def annotate_feature(
    feature: Mapping[str, Any],
    *,
    embodiment: str,
    origin_data: str,
    default_description: str,
) -> dict[str, Any]:
    """Copy one feature and append provenance to every description it contains."""
    result = deepcopy(dict(feature))
    suffix = source_metadata_suffix(embodiment, origin_data)

    def visit(value: Any) -> None:
        if isinstance(value, dict):
            for key, child in list(value.items()):
                if key == "description" and isinstance(child, str):
                    description = child.strip()
                    missing = []
                    if "Embodiment:" not in description:
                        missing.append(f"Embodiment: {embodiment.strip()}.")
                    if "OriginData:" not in description:
                        missing.append(f"OriginData: {origin_data.strip()}.")
                    if missing:
                        value[key] = " ".join([description, *missing]).strip()
                else:
                    visit(child)
        elif isinstance(value, list):
            for child in value:
                visit(child)

    visit(result)
    if "description" not in result:
        result["description"] = f"{default_description.strip()} {suffix}"
    return result


def annotate_features(
    features: Mapping[str, Mapping[str, Any]],
    *,
    embodiment: str,
    origins: OriginResolver,
    default_description: Callable[[str], str] | None = None,
) -> dict[str, dict[str, Any]]:
    """Annotate all feature descriptions with embodiment and raw source paths."""
    annotated: dict[str, dict[str, Any]] = {}
    for key, feature in features.items():
        origin_data = origins(key) if callable(origins) else origins.get(key)
        if not origin_data:
            raise KeyError(f"No OriginData mapping declared for feature {key!r}")
        fallback = (
            default_description(key)
            if default_description is not None
            else f"Converted feature {key}."
        )
        annotated[key] = annotate_feature(
            feature,
            embodiment=embodiment,
            origin_data=origin_data,
            default_description=fallback,
        )
    return annotated


def validate_feature_descriptions(features: Mapping[str, Mapping[str, Any]]) -> None:
    """Fail when a feature description omits the standardized provenance fields."""
    def validate(value: Any, path: str) -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                child_path = f"{path}.{key}"
                if key == "description":
                    if not isinstance(child, str) or not child.strip():
                        raise ValueError(f"{child_path} is empty")
                    if "Embodiment:" not in child:
                        raise ValueError(f"{child_path} has no Embodiment field")
                    if "OriginData:" not in child:
                        raise ValueError(f"{child_path} has no OriginData field")
                else:
                    validate(child, child_path)
        elif isinstance(value, list):
            for index, child in enumerate(value):
                validate(child, f"{path}[{index}]")

    for key, feature in features.items():
        description = feature.get("description")
        if not isinstance(description, str) or not description.strip():
            raise ValueError(f"Feature {key!r} has no description")
        validate(feature, f"features.{key}")


def annotate_dataset_info(
    dataset_root: str | Path,
    *,
    embodiment: str | None = None,
) -> Path:
    """Annotate writer-generated features in an existing ``meta/info.json``."""
    dataset_root = Path(dataset_root).expanduser().resolve()
    info_path = dataset_root / "meta" / "info.json"
    info = json.loads(info_path.read_text(encoding="utf-8"))
    features = info.get("features")
    if not isinstance(features, dict) or not features:
        raise ValueError(f"No features found in {info_path}")

    resolved_embodiment = embodiment or _infer_embodiment(features)

    def origin_for_feature(key: str) -> str:
        if key in LEROBOT_GENERATED_ORIGINS:
            return LEROBOT_GENERATED_ORIGINS[key]
        return "source path already declared in this converted feature description"

    info["features"] = annotate_features(
        features,
        embodiment=resolved_embodiment,
        origins=origin_for_feature,
        default_description=lambda key: f"LeRobot dataset feature {key}.",
    )
    validate_feature_descriptions(info["features"])

    temp_path = info_path.with_suffix(".json.tmp")
    temp_path.write_text(
        json.dumps(info, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    os.replace(temp_path, info_path)
    return info_path


def _infer_embodiment(features: Mapping[str, Mapping[str, Any]]) -> str:
    marker = "Embodiment:"
    terminator = ". OriginData:"
    embodiments = set()
    for feature in features.values():
        description = feature.get("description")
        if not isinstance(description, str) or marker not in description:
            continue
        remainder = description.split(marker, 1)[1]
        if terminator not in remainder:
            continue
        embodiments.add(remainder.split(terminator, 1)[0].strip())
    if len(embodiments) != 1:
        raise ValueError(
            "Cannot infer one embodiment from feature descriptions; pass embodiment explicitly"
        )
    return embodiments.pop()
